import 'package:flutter/material.dart';

import 'generated/summary_scopes.g.dart';
import 'src/specs_editor_app.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Register the summary scopes declared in `buildkit.yaml` (generated by
  // tom_dart_editor_bundler) so code-typed spec fields analyse against the right
  // bundle. Awaited before `runApp` so the registry is populated before the first
  // frame; code fields then probe `SummaryScopeRegistry.isRegistered(...)`
  // synchronously. Guarded: a dev checkout without the generated `.sum` assets
  // simply leaves scopes unregistered and those fields fall back to plain text.
  try {
    await SummaryScopes.initialize();
  } catch (error, stack) {
    debugPrint('Summary scope init skipped: $error');
    debugPrintStack(stackTrace: stack);
  }
  runApp(const SpecsEditorApp());
}
